// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.eclipse.rdf4j.sail.lmdb.frontier.SyntheticQuadSnapshot.predicate;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * One planner join estimate must have a work bound. Leaves and path programs already have one; Omni bridges used to
 * scan the sampled side completely and issue one full candidate-cell scan per sampled key and lane.
 */
class FrontierOmniBridgeWorkBudgetTest {

	private static final long HUB = 5_000_000L;

	/**
	 * A 4,000-key sampled side whose keys all have positive degree, laid out in two huge Omni cells, forces one full
	 * candidate-cell scan (up to the 8,192-row witness ceiling) per key per lane without a budget.
	 */
	@Test
	void singleJoinEstimateHasBoundedPlanningWork(@TempDir Path directory) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 0; i < 50_000; i++) {
			rows.add(new long[] { 10_000_000L + i, 7L, 1_000_000L + (i % 4_000), 0L });
			rows.add(new long[] { 1_000_000L + (i % 4_000), 8L, 20_000_000L + i, 0L });
		}
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(93L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 2, 8_192, 256, 8L * 1024L * 1024L);
		try (LmdbStatisticsService service = SyntheticQuadSnapshot.buildService(directory, snapshot, config)) {
			FrontierJoinProbe probe = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0);
			long work;
			FrontierJoinEstimate warm;
			try (FrontierStatisticsView view = service.openView(snapshot.snapshotEpoch())) {
				assertTrue(view.ready());
				warm = view.estimateJoin(probe);
				work = view.candidateRowsVisited();
			}
			long best = Long.MAX_VALUE;
			for (int run = 0; run < 3; run++) {
				try (FrontierStatisticsView view = service.openView(snapshot.snapshotEpoch())) {
					long started = System.nanoTime();
					view.estimateJoin(probe);
					best = Math.min(best, System.nanoTime() - started);
				}
			}
			FrontierOmniIndex.Scratch omniScratch = new FrontierOmniIndex.Scratch();
			FrontierJoinEstimate omniEstimate;
			try (FrontierStatisticsLease lease = service.acquire(snapshot.snapshotEpoch())) {
				FrontierOmniIndex omni = new FrontierOmniIndex(service.currentManifest().orElseThrow(),
						lease.shards());
				omniEstimate = omni.estimateJoin(probe, omniScratch);
			}
			String description = "estimate=" + warm + " exact=" + exact + " candidateRowsVisited=" + work
					+ " omniBridge=" + omniEstimate + " omniBridgeRows=" + omniScratch.candidateRowsVisited()
					+ " best-of-3 millis=" + best / 1_000_000.0d;
			assertTrue(work <= FrontierOmniIndex.MAXIMUM_ESTIMATE_WORK,
					"one two-pattern join estimate visited " + work + " candidate rows, above the per-estimate bound "
							+ FrontierOmniIndex.MAXIMUM_ESTIMATE_WORK + "; " + description);
			assertTrue(omniScratch.candidateRowsVisited() <= FrontierOmniIndex.MAXIMUM_BRIDGE_WORK,
					"both orientations of one Omni bridge must stay within the bridge budget "
							+ FrontierOmniIndex.MAXIMUM_BRIDGE_WORK + "; " + description);
			if (warm.fallbackReason() == FrontierFallbackReason.NONE) {
				assertTrue(warm.lowerRows() <= exact && exact <= warm.upperRows(),
						"a budgeted estimate must keep exact inside its interval; " + description);
			}
			if (omniEstimate.fallbackReason() == FrontierFallbackReason.NONE) {
				assertTrue(omniEstimate.lowerRows() <= exact && exact <= omniEstimate.upperRows(),
						"a budget-limited bridge must be a typed unknown or keep exact inside its interval; "
								+ description);
			}
			assertTrue(best < 50_000_000L, "one two-pattern join estimate took " + best / 1_000_000.0d
					+ " ms; the planner issues many of these per query; " + description);
		}
	}

	/** The reverse orientation evaluated for a weak forward bridge shares the same per-estimate budget. */
	@Test
	void bothBridgeOrientationsShareOnePerEstimateBudget(@TempDir Path directory) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 1; i <= 20_000; i++) {
			rows.add(new long[] { 1_000_000L + i, 7L, 2_000_000L + i, 0L });
		}
		for (int j = 1; j <= 8; j++) {
			rows.add(new long[] { 3_000_000L + j, 7L, HUB, 0L });
		}
		for (int m = 1; m <= 20_000; m++) {
			rows.add(new long[] { HUB, 8L, 6_000_000L + m, 0L });
			rows.add(new long[] { 7_000_000L + m, 8L, 8_000_000L + m, 0L });
		}
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(91L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 1024, 256, 256, 2L * 1024L * 1024L);
		try (LmdbStatisticsService service = SyntheticQuadSnapshot.buildService(directory, snapshot, config);
				FrontierStatisticsView view = service.openView(snapshot.snapshotEpoch());
				FrontierStatisticsLease lease = service.acquire(snapshot.snapshotEpoch())) {
			assertTrue(view.ready());
			long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0);
			FrontierJoinProbe probe = new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0);
			FrontierJoinEstimate estimate = view.estimateJoin(probe);
			long work = view.candidateRowsVisited();
			assertTrue(work <= FrontierOmniIndex.MAXIMUM_ESTIMATE_WORK,
					"forward plus reverse orientation visited " + work + " candidate rows; estimate=" + estimate);
			assertTrue(estimate.fallbackReason() == FrontierFallbackReason.NONE
					&& estimate.pointRows() >= exact / 16.0d,
					"hidden hub must stay estimable within the budget: "
							+ estimate + " exact=" + exact + " work=" + work);

			FrontierOmniIndex omni = new FrontierOmniIndex(service.currentManifest().orElseThrow(), lease.shards());
			FrontierOmniIndex.Scratch scratch = new FrontierOmniIndex.Scratch();
			FrontierJoinEstimate bridge = omni.estimateJoin(probe, scratch);
			assertTrue(scratch.candidateRowsVisited() <= FrontierOmniIndex.MAXIMUM_BRIDGE_WORK,
					"forward plus reverse orientation of one bridge visited " + scratch.candidateRowsVisited()
							+ " candidate rows; bridge=" + bridge);
			assertTrue(bridge.fallbackReason() == FrontierFallbackReason.NONE && bridge.pointRows() >= exact / 16.0d,
					"the reverse orientation must still find the hidden hub within the shared bridge budget: "
							+ bridge + " exact=" + exact);
		}
	}

	/**
	 * With a mapped Omni mutation layer the sampled side cannot be read as a priority prefix, so a bridge whose full
	 * scans exceed the budget must decline to a typed unknown (or stay exact-covering); it must never report a point
	 * computed from a truncated scan.
	 */
	@Test
	void budgetExhaustionWithMutationLayersDeclinesInsteadOfTruncating(@TempDir Path directory) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		for (int i = 0; i < 50_000; i++) {
			rows.add(new long[] { 10_000_000L + i, 7L, 1_000_000L + (i % 4_000), 0L });
			rows.add(new long[] { 1_000_000L + (i % 4_000), 8L, 20_000_000L + i, 0L });
		}
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(93L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				512L * 1024L * 1024L, 2, 8_192, 256, 8L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				256L * 1024L * 1024L, 32L * 1024L * 1024L, 64L * 1024L * 1024L, 32L * 1024L * 1024L);
		FrontierStatisticsManifest base = FrontierStatisticsBuilder.build(
				directory, 1L, -1L, snapshot, governor, config);
		FrontierStatisticsManifest delta = FrontierStatisticsDeltaBuilder.build(directory, base,
				List.of(new FrontierMutation(94L, 94L, true, true, 30_000_000L, 7L, 1_000_000L, 0L)),
				governor, config);
		FrontierStatisticsManifestStore store = new FrontierStatisticsManifestStore(directory,
				NioFrontierFileOps.INSTANCE);
		store.publish(base);
		store.publish(delta);
		long insertedRowDegree = rows.stream().filter(row -> row[1] == 8L && row[0] == 1_000_000L).count();
		long exact = snapshot.exactPredicateJoin(7L, 2, 8L, 0) + insertedRowDegree;
		try (LmdbStatisticsService service = LmdbStatisticsService.open(directory, governor,
				1024L * 1024L * 1024L, 60_000L);
				FrontierStatisticsLease lease = service.acquire(delta.coveredEpoch())) {
			assertTrue(lease.ready(), () -> "delta generation must be ready: " + service.status());
			FrontierOmniIndex omni = new FrontierOmniIndex(service.currentManifest().orElseThrow(), lease.shards());
			assertTrue(omni.mutationLayerCount() > 0, "the test needs a mapped Omni mutation layer");
			FrontierOmniIndex.Scratch scratch = new FrontierOmniIndex.Scratch();
			FrontierJoinEstimate bridge = omni.estimateJoin(
					new FrontierJoinProbe(predicate(7L), 2, predicate(8L), 0), scratch);
			assertTrue(scratch.candidateRowsVisited() <= FrontierOmniIndex.MAXIMUM_BRIDGE_WORK,
					"bridge visited " + scratch.candidateRowsVisited() + " rows: " + bridge);
			assertTrue(bridge.fallbackReason() != FrontierFallbackReason.NONE
					|| bridge.lowerRows() <= exact && exact <= bridge.upperRows(),
					"a budget-limited bridge over mutation layers must be a typed unknown or cover exact=" + exact
							+ ": " + bridge);
		}
	}
}
